import xarray as xr
import numpy as np
from xarray.indexes import NDPointIndex

def test_ndpointindex_1d_coords():
    ds = xr.Dataset(
        coords={
            "x": ("points", np.linspace(0, 10, 20)),
            "y": ("points", np.linspace(15, 8, 20)),
        }
    )
    try:
        ds_indexed = ds.set_xindex(("x", "y"), NDPointIndex)
        print("Successfully created NDPointIndex with 1D coordinates")
    except ValueError as e:
        print(f"Failed to create NDPointIndex: {e}")
        raise e

if __name__ == "__main__":
    test_ndpointindex_1d_coords()

